#!/usr/bin/env python3
"""Build a complete delivery from current sources, never an older delivery ZIP.
Requires the tested site/dist-demo, current evidence, Python 3, Node, Playwright
and Chromium. No runtime data, secrets, dependency caches or old ZIPs exported.
"""
import base64
import hashlib
import html
import json
from pathlib import Path
import shutil
import subprocess
import tempfile
import zipfile

ROOT = Path(__file__).resolve().parent.parent
from delivery_landing import render as render_landing
from delivery_docs import VERSION, APP_VERSION, PUBLIC_APP_VERSION, DOCS, GUIDE_DOCS, MIRRORS, digest, linked, markdown, page

NAME = f'Salamatban-Complete-Delivery-v{VERSION}'
OUTPUT = ROOT / 'deliverables' / f'{NAME}.zip'
BUILD = ROOT / 'site/dist-demo'

if not (BUILD/'release.json').is_file():raise SystemExit('Run npm run build:demo first')
release=json.loads((BUILD/'release.json').read_text())
evidence=json.loads((ROOT/'review-evidence/ux-release.json').read_text())
if evidence['version']!=APP_VERSION or release['version']!=APP_VERSION:raise SystemExit('App/evidence versions do not match this delivery')
facility_snapshot_path = BUILD/'data/care-facilities.geoapify.json'
facility_snapshot = json.loads(facility_snapshot_path.read_text())
if facility_snapshot.get('schemaVersion') != 1 or facility_snapshot.get('provider') != 'geoapify' or facility_snapshot.get('mode') != 'snapshot':raise SystemExit('Expected a dated Geoapify snapshot in the built website')
if digest(facility_snapshot_path) != digest(ROOT/'site/public/data/care-facilities.geoapify.json'):raise SystemExit('Built facility snapshot does not match current source')

with tempfile.TemporaryDirectory(prefix='salamatban-delivery-') as temp:
 dest=Path(temp)/NAME;dest.mkdir()
 for directory in ['documents','technical']: (dest/directory).mkdir()
 for n in ['Start-Mac-Linux.command','Start-Windows.cmd','serve-demo.py']:shutil.copy2(ROOT/'scripts/delivery-template'/n,dest/n)
 for n in ['Start-Mac-Linux.command','serve-demo.py']:(dest/n).chmod(0o755)
 try:
  git_root=Path(subprocess.check_output(['git','rev-parse','--show-toplevel'],cwd=ROOT,stderr=subprocess.DEVNULL).decode().strip())
 except subprocess.CalledProcessError:git_root=None
 source_paths=(subprocess.check_output(['git','ls-files','--cached','--others','--exclude-standard','-z'],cwd=ROOT).decode().split('\0') if git_root==ROOT else [p.relative_to(ROOT).as_posix() for p in ROOT.rglob('*') if p.is_file() and not any(x in {'node_modules','.git','.wrangler','.test-build','dist','dist-demo','dist-maps-server','.maps-data','__pycache__'} for x in p.relative_to(ROOT).parts)])
 for name in sorted(set(source_paths)):
  if not name or name.startswith('deliverables/Salamatban-Complete-Delivery-') or name in {'review-evidence/ux-archive-validation.json','review-evidence/showcase-publication.json','deliverables/delivery-manifest.json'}:continue
  if name.startswith('review-evidence/') and Path(name).name not in {'account-peek-tests.json','account-peek-member-desktop.png','account-peek-staff-desktop.png','account-peek-mobile.png','ux-baseline-v2.4.4.json','login-layout-tests.json','login-layout-desktop.png','login-layout-mobile.png','login-layout-complete.png','ux-baseline-v2.4.3.json','grouped-intake-tests.json','workspace-tests.json','urgent-experience-tests.json','care-mobile-tests.json','care-path-desktop.png','care-path-mobile.png','mobile-login-320.png','ux-baseline-v2.4.2.json','paid-workspace-tests.json','paid-workspace-desktop.png','paid-workspace-mobile.png','ux-baseline-v2.4.1.json','presentation-tests.json','value-visual-review.json','value-visual-desktop.png','value-visual-mobile.png','ux-baseline-v2.4.json','delivery-source-rebuild.json','demo-public-browser.json','complete-demo-tests.json','demo-document-review.json','ux-baseline-v2.3.2.json','ux-baseline-v2.3.json','geoapify-proxy-tests.json','geoapify-readiness.json','geoapify-snapshot-review.json','maps-server-tests.json','facility-snapshot-tests.json','geoapify-snapshot-collection.json','neshan-proxy-tests.json','maps-config-tests.json','neshan-readiness.json','facility-live-probe.json','facility-browser-probe.json','city-catalog-tests.json','city-input-tests.json','facility-lookup-tests.json','reference-experience-tests.json','layout-stability-tests.json','controls-stability-tests.json','component-stability-measurements.json','urgent-experience-tests.json','critical-draft-tests.json','flat-surfaces-validation.json','flat-discovery-1440.png','flat-discovery-390.png','grouped-intake-tests.json','workspace-tests.json','visual-tests.json','visual-home-1280.png','visual-home-390.png','visual-waiting.png','visual-program.png','visual-consent-mobile.png','visual-consent-desktop.png','visual-long-terms.png','api-tests.json','ux-release.json','ux-publication.json','ux-tests.json','workflow-tests.json','edge-tests.json','ux-final-browser.json','architecture-database-validation.json','showcase-browser.json','showcase-desktop.png','showcase-mobile.png','journey-tests.json','journey-welcome-1440.png','journey-welcome-390.png','journey-reasons-desktop.png','journey-reasons-mobile.png','login-browser.json','login-desktop.png','login-mobile.png','ux-baseline-v1.7.json'}:continue
  if name.startswith('deliverables/') and Path(name).suffix=='.json' and name not in {'deliverables/showcase/diagrams.json'} and not name.startswith(('deliverables/showcase/user-flow/','deliverables/showcase/workflow-v2.2/')):continue
  if name=='scripts/create_deliverables.py':continue
  path=ROOT/name;parts=Path(name).parts
  if any(p in {'.git','node_modules','.wrangler','.test-build','dist','dist-demo','dist-maps-server','.maps-data','.next','__pycache__'} for p in parts):continue
  if path.is_symlink():raise SystemExit(f'Source symlink requires review: {name}')
  if not path.is_file():continue
  allowed=name.startswith(('deliverables/showcase/','deliverables/previews/')) or name in {'README.md','AGENTS.md'} or name.startswith(('site/','scripts/')) or (name.startswith(('deliverables/','review-evidence/','deployments/')) and path.suffix in {'.md','.csv','.sql','.json','.log'}) or name in {'deliverables/Salamatban-Visual-Identity.pdf','deliverables/Salamatban-Preview.png','deliverables/Salamatban-Mobile-Preview.png'} or (name.startswith('review-evidence/') and path.suffix=='.png')
  if not allowed or (path.name.startswith(('.env','.dev.vars')) and path.name!='.dev.vars.example') or path.suffix in {'.sqlite','.db','.pem','.tsbuildinfo'} or (path.suffix=='.zip' and not name.startswith(('deliverables/showcase/user-flow/','deliverables/showcase/workflow-v2.2/'))):continue
  target=dest/'source'/name;target.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(path,target)
 shutil.copytree(BUILD,dest/'website')
 mirrors=[]
 for origin,target in MIRRORS.items():
  p=dest/target;p.parent.mkdir(parents=True,exist_ok=True)
  if p.suffix=='.md':p.write_text(linked((ROOT/origin).read_text(),origin,target))
  else:shutil.copy2(ROOT/origin,p)
  mirrors.append({'source':'source/'+origin,'path':target,'transformation':'relative Markdown links only' if p.suffix=='.md' else 'identical'})
 shutil.copy2(ROOT/'deliverables/Salamatban-Visual-Identity.pdf',dest/'documents/Salamatban-Visual-Identity.pdf')
 (dest/'presentation').mkdir()
 shutil.copytree(ROOT/'deliverables/showcase',dest/'presentation/assets')
 font=base64.b64encode((ROOT/'site/public/fonts/PeydaWebFaNum-Regular.woff2').read_bytes()).decode()
 css='@font-face{font-family:Peyda;src:url(data:font/woff2;base64,'+font+')}*{box-sizing:border-box}body{font-family:Peyda,sans-serif;line-height:1.9;color:#153653;margin:0;background:#f5f9ff}main{max-width:1050px;margin:auto;padding:32px}section{background:white;padding:24px;margin:20px 0;border:1px solid #d7e4ef;border-radius:16px}a{color:#245abb;overflow-wrap:anywhere}h1,h2,h3,h4,h5{line-height:1.5;break-after:avoid}table{border-collapse:collapse;width:100%;table-layout:fixed;font-size:12px}td,th{border:1px solid #ccd8e3;padding:7px;vertical-align:top;overflow-wrap:anywhere}code{direction:ltr;unicode-bidi:embed;overflow-wrap:anywhere}pre{direction:ltr;text-align:left;white-space:pre-wrap;font-size:11px}img{max-width:100%;height:auto}tr{break-inside:avoid}@media(max-width:600px){main{padding:12px}section{padding:14px}}@media print{body{background:white;font-size:12px}main{padding:0;max-width:none}section{border:0;border-radius:0;padding:0;break-before:page}a{color:inherit;text-decoration:none}table{font-size:10px}pre{font-size:9px}}@page{size:A4;margin:16mm}'
 intro='<h1>سلامت‌بان — راهنمای معرفی و بررسی محصول</h1><p>برنامهٔ داخل بسته: <strong>۲٫۴٫۵</strong>؛ فهرست تاریخ‌دار مراکز از Geoapify/OpenStreetMap و مسیریابی در نشان است. جست‌وجوی زندهٔ عمومی هنوز فعال نیست. این راهنما برای دیدن محصول و ارائهٔ بازخورد است.</p>'
 for n in ['index.html','00-START-HERE.html']:(dest/n).write_text(render_landing(ROOT))
 (dest/'README-fa.txt').write_text('بسته و برنامهٔ سلامت‌بان ۲٫۴٫۵؛ فهرست واقعی و تاریخ‌دار مراکز برای شهرهای تحت پوشش از Geoapify/OpenStreetMap می‌آید و مسیریابی در نشان باز می‌شود. این دادهٔ ذخیره‌شده است؛ جست‌وجوی زنده هنوز فعال نیست. technical/GEOAPIFY-INTEGRATION-fa.md را ببینید.\nاز index.html یا 00-START-HERE.html شروع کنید.\nهمهٔ ZIP را استخراج کنید؛ Python 3 برای اجرای محلی لازم است. اجراگر ویندوز یا مک/لینوکس یا python3 serve-demo.py را اجرا کنید.\nwebsite/ خروجی آماده، source/ سورس و منابع جاری، technical/ اسناد با لینک متناسب با بسته و documents/ راهنمای HTML/PDF است.\nمرجع جاری: technical/DELIVERY-STATUS-fa.md. گزارش‌های تاریخی، طرح PostgreSQL آینده و تصاویر هویت در آن مشخص شده‌اند.\nراهنمای کوتاه از متن معرفی فعلی ساخته شده؛ CONTENTS.json فهرست منابع و MANIFEST.json هش همه فایل‌هاست.\nنسخه عمومی نمایشی و با داده محلی مرورگر است. پرداخت و SMS واقعی ندارد. بازکردن نقشه و مسیر اینترنت می‌خواهد؛ دادهٔ ذخیره‌شدهٔ مراکز همراه بسته است.\n')
 guide_output='documents/Salamatban-Complete-Guide-fa.html'
 toc='<nav><h2>فهرست</h2>'+''.join(f'<p><a href="#doc-{i}">{html.escape((ROOT/"deliverables"/n).read_text().splitlines()[0].lstrip("# "))}</a></p>' for i,n in enumerate(GUIDE_DOCS))+'</nav>'
 sections=[]
 for i,n in enumerate(GUIDE_DOCS):
  origin='deliverables/'+n
  sections.append(f'<section id="doc-{i}">'+markdown(linked((ROOT/origin).read_text(),origin,guide_output))+'</section>')
 guide=dest/guide_output;guide.write_text(page('سلامت‌بان — راهنمای کوتاهٔ معرفی محصول',''.join(sections),css+'section:first-of-type{break-before:auto}'))
 renderer="""const {chromium}=await import(process.argv[1]);const {readFile}=await import('node:fs/promises');const b=await chromium.launch({executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});try{const p=await b.newPage();await p.setContent(await readFile(process.argv[2],'utf8'),{waitUntil:'load'});await p.evaluate(()=>document.fonts.ready);await p.pdf({path:process.argv[3],format:'A4',printBackground:true,preferCSSPageSize:true});}finally{await b.close();}"""
 subprocess.run(['node','--input-type=module','-e',renderer,(ROOT/'site/node_modules/playwright/index.mjs').as_uri(),str(guide),str(guide.with_suffix('.pdf'))],check=True)
 catalog={'packageVersion':VERSION,'appVersion':APP_VERSION,'publicAppVersion':PUBLIC_APP_VERSION,'publicationStatus':'Static v2.4.5 release has two isolated demo lanes, ten fictional cases and ephemeral read-only paid previews, plus dated real Geoapify facility snapshots and Neshan destination links. Public HTTPS verification is recorded separately in ux-publication.json; no live search gateway is deployed.','scope':'Paired fictional doctors/coordinators with disjoint physician assignment and shared coordination queue. Record-based hover, keyboard and touch account previews show tenure, separate registration/action progress and real responsibility counts; additive upgrade preserves edited records and explicit administrator assignments. Two-band login: right form, full-height professional photo on the left, categorized demo accounts below, one desktop viewport and responsive phone entry. Illustrated care journey with real action completion and touch-friendly mobile navigation, forms and role queues. Compact illustrated member dashboard, operational programme/document/appointment tabs, responsive appointment stages and first-visit font loading. Original blue care artwork and record-based action completion. Two isolated browser-local demo lanes; ten seeded fictional cases, three year histories, 25 watermarked PDFs and seven JPEGs; read-only paid preview leaves the current account and draft intact. Persian RTL browser demo with photographic blue login, preserved OTP/demo accounts, grouped intake, stable feedback geometry, transparent live artwork, actionable member/doctor/coordinator/admin workspaces, synthetic payments and followup. Urgent assistance uses current symptom answers and dated real Geoapify facility snapshots with explicit city coverage, source attribution and Neshan destination links. The server-only Geoapify gateway and standalone Node VPS wrapper are prepared for later deployment; public live search is not active.','guideSources':['source/deliverables/'+n for n in GUIDE_DOCS],'mirrors':mirrors,'currentAppEvidence':['source/review-evidence/'+n for n in ['ux-release.json','account-peek-tests.json','login-layout-tests.json','complete-demo-tests.json','presentation-tests.json','paid-workspace-tests.json','care-mobile-tests.json','grouped-intake-tests.json','workspace-tests.json','urgent-experience-tests.json','demo-public-browser.json']],'retainedComponentEvidence':['source/review-evidence/'+n for n in ['value-visual-review.json','demo-document-review.json','geoapify-proxy-tests.json','maps-config-tests.json','geoapify-readiness.json','facility-lookup-tests.json','reference-experience-tests.json','city-catalog-tests.json','city-input-tests.json','layout-stability-tests.json','controls-stability-tests.json','critical-draft-tests.json','visual-tests.json','journey-tests.json','api-tests.json','workflow-tests.json','edge-tests.json','ux-tests.json','login-browser.json','ux-final-browser.json']],'publicDeploymentEvidence':'source/review-evidence/ux-publication.json','demo':{'lanes':['practice','complete'],'fictionalCases':10,'yearHistoryCases':3,'pdfs':25,'images':7,'asOf':'2026-10-08','customerPreview':'isolated ephemeral read-only','documentsManifest':'website/demo/documents/manifest.json','sourceScenarios':'source/site/demo/fixtures/cases.json'},'publicDeploymentEvidenceScope':'HTTPS publication checks for the version stated in ux-publication.json; static publication does not activate the live Geoapify gateway.','baselineEvidenceScope':'Retained v2.3 test results and OSM/Nominatim probes, plus v2.3.1 Neshan preparation checks, are previous-release evidence, not live Geoapify gateway activation.','baselineEvidence':['source/review-evidence/ux-baseline-v2.4.4.json','source/review-evidence/ux-baseline-v2.4.3.json','source/review-evidence/ux-baseline-v2.4.2.json','source/review-evidence/ux-baseline-v2.4.1.json','source/review-evidence/ux-baseline-v2.4.json','source/review-evidence/ux-baseline-v2.3.2.json','source/review-evidence/ux-baseline-v2.3.json','source/review-evidence/neshan-proxy-tests.json','source/review-evidence/neshan-readiness.json','source/review-evidence/facility-live-probe.json','source/review-evidence/facility-browser-probe.json','source/review-evidence/ux-baseline-v1.7.json','source/review-evidence/flat-surfaces-validation.json','source/review-evidence/component-stability-measurements.json'],'packageEvidence':'source/review-evidence/showcase-browser.json','evidenceScope':'Current browser/build/showcase checks and retained evidence for unchanged components are distinguished in ux-release.json; older baseline stays labeled','designEvidence':'architecture-database-validation.json validates the proposed PostgreSQL schema only','visuals':'presentation/assets contains six recovered architecture diagrams as PNG/SVG and sixteen synthetic product screenshots, including the complete case catalog and paid preview, plus the comprehensive target user-flow viewer'}
 catalog['mapsData']={'mode':'snapshot','provider':'geoapify','directionsProvider':'neshan','path':'website/data/care-facilities.geoapify.json','source':'source/site/public/data/care-facilities.geoapify.json','sha256':digest(facility_snapshot_path),'generatedAt':facility_snapshot['generatedAt'],'providerRevision':facility_snapshot.get('providerRevision'),'coverage':facility_snapshot['coverage'],'attribution':facility_snapshot['attribution'],'facilityCards':sum(len(entry['facilities']) for entry in facility_snapshot['entries']),'countScope':'Card count across city entries; nearby cities may list the same facility.','liveGatewayDeployed':False}
 (dest/'CONTENTS.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n')
 entries=[{'path':p.relative_to(dest).as_posix(),'bytes':p.stat().st_size,'sha256':digest(p)} for p in sorted(dest.rglob('*')) if p.is_file()]
 (dest/'MANIFEST.json').write_text(json.dumps({'version':VERSION,'appVersion':APP_VERSION,'selfExcluded':'MANIFEST.json','files':entries},ensure_ascii=False,indent=2)+'\n')
